(function() {
    'use strict';

    class DespuesAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Después';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    briefingKey: 'round1_briefing',
                    feedbackKey: 'round1_feedback',
                    d1: { labelKey: 'r1_d1_label', options: [
                        { value: 1, textKey: 'r1_d1_opt1', learning: 1, safety: 0, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r1_d1_opt2', learning: 3, safety: 2, risk: 0, revenue: 0 },
                        { value: 3, textKey: 'r1_d1_opt3', learning: 0, safety: -1, risk: 0, revenue: 0 }
                    ]},
                    d2: { labelKey: 'r1_d2_label', options: [
                        { value: 1, textKey: 'r1_d2_opt1', learning: 3, safety: 1, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r1_d2_opt2', learning: 1, safety: 1, risk: 0, revenue: 0 },
                        { value: 3, textKey: 'r1_d2_opt3', learning: 0, safety: -1, risk: 0, revenue: 0 }
                    ]},
                    d3: { labelKey: 'r1_d3_label', options: [
                        { value: 1, textKey: 'r1_d3_opt1', learning: 3, safety: 2, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r1_d3_opt2', learning: 1, safety: 0, risk: 0, revenue: 0 },
                        { value: 3, textKey: 'r1_d3_opt3', learning: 2, safety: 0, risk: 0, revenue: 0 }
                    ]}
                },
                {
                    titleKey: 'round2_title',
                    briefingKey: 'round2_briefing',
                    feedbackKey: 'round2_feedback',
                    d1: { labelKey: 'r2_d1_label', options: [
                        { value: 1, textKey: 'r2_d1_opt1', learning: 0, safety: 0, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r2_d1_opt2', learning: 2, safety: 1, risk: 0, revenue: 0 },
                        { value: 3, textKey: 'r2_d1_opt3', learning: 3, safety: 2, risk: 0, revenue: 0 }
                    ]},
                    d2: { labelKey: 'r2_d2_label', options: [
                        { value: 1, textKey: 'r2_d2_opt1', learning: 0, safety: -2, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r2_d2_opt2', learning: 1, safety: 0, risk: 0, revenue: 0 },
                        { value: 3, textKey: 'r2_d2_opt3', learning: 3, safety: 2, risk: 0, revenue: 0 }
                    ]},
                    d3: { labelKey: 'r2_d3_label', options: [
                        { value: 1, textKey: 'r2_d3_opt1', learning: 2, safety: 3, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r2_d3_opt2', learning: 1, safety: 1, risk: 0, revenue: 0 },
                        { value: 3, textKey: 'r2_d3_opt3', learning: 0, safety: -1, risk: 0, revenue: 0 }
                    ]}
                },
                {
                    titleKey: 'round3_title',
                    briefingKey: 'round3_briefing',
                    feedbackKey: 'round3_feedback',
                    d1: { labelKey: 'r3_d1_label', options: [
                        { value: 1, textKey: 'r3_d1_opt1', learning: 1, safety: 0, risk: 3, revenue: 150000 },
                        { value: 2, textKey: 'r3_d1_opt2', learning: 1, safety: 0, risk: 2, revenue: 100000 },
                        { value: 3, textKey: 'r3_d1_opt3', learning: 0, safety: 1, risk: 1, revenue: 50000 }
                    ]},
                    d2: { labelKey: 'r3_d2_label', options: [
                        { value: 1, textKey: 'r3_d2_opt1', learning: 0, safety: 0, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r3_d2_opt2', learning: 1, safety: 0, risk: 3, revenue: 200000 },
                        { value: 3, textKey: 'r3_d2_opt3', learning: 1, safety: 0, risk: 2, revenue: 150000 }
                    ]},
                    d3: { labelKey: 'r3_d3_label', options: [
                        { value: 1, textKey: 'r3_d3_opt1', learning: 0, safety: -1, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r3_d3_opt2', learning: 1, safety: 2, risk: 3, revenue: 150000 },
                        { value: 3, textKey: 'r3_d3_opt3', learning: 0, safety: 1, risk: 2, revenue: 100000 }
                    ]}
                },
                {
                    titleKey: 'round4_title',
                    briefingKey: 'round4_briefing',
                    feedbackKey: 'round4_feedback',
                    d1: { labelKey: 'r4_d1_label', options: [
                        { value: 1, textKey: 'r4_d1_opt1', learning: 0, safety: 0, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r4_d1_opt2', learning: 2, safety: 1, risk: 1, revenue: 100000 },
                        { value: 3, textKey: 'r4_d1_opt3', learning: 3, safety: 1, risk: 3, revenue: 200000 }
                    ]},
                    d2: { labelKey: 'r4_d2_label', options: [
                        { value: 1, textKey: 'r4_d2_opt1', learning: 2, safety: 3, risk: 0, revenue: 0 },
                        { value: 2, textKey: 'r4_d2_opt2', learning: 0, safety: 1, risk: 0, revenue: 0 },
                        { value: 3, textKey: 'r4_d2_opt3', learning: 0, safety: -1, risk: 0, revenue: 0 }
                    ]},
                    d3: { labelKey: 'r4_d3_label', options: [
                        { value: 1, textKey: 'r4_d3_opt1', learning: 2, safety: 0, risk: 3, revenue: 200000 },
                        { value: 2, textKey: 'r4_d3_opt2', learning: 1, safety: 0, risk: 1, revenue: 50000 },
                        { value: 3, textKey: 'r4_d3_opt3', learning: 0, safety: 0, risk: 0, revenue: 0 }
                    ]}
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    learningScore: 10,
                    safetyScore: 20,
                    riskScore: 10,
                    revenueProtected: 0,
                    totalRevAtRisk: 1100000,
                    learningHistory: [],
                    safetyHistory: [],
                    riskHistory: [],
                    revenueHistory: [],
                    roundScoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decision1: 1,
                    decision2: 1,
                    decision3: 1
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var feedbackPanel = document.getElementById('feedbackPanel');
            if (feedbackPanel) feedbackPanel.style.display = 'none';

            var d1 = document.getElementById('decision1Input');
            var d2 = document.getElementById('decision2Input');
            var d3 = document.getElementById('decision3Input');
            if (d1) decisions.decision1 = parseInt(d1.value);
            if (d2) decisions.decision2 = parseInt(d2.value);
            if (d3) decisions.decision3 = parseInt(d3.value);

            if (!decisions.decision1 || !decisions.decision2 || !decisions.decision3) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var learningGain = 0;
            var safetyGain = 0;
            var riskGain = 0;
            var revenueGain = 0;

            var decisionSets = [
                { config: round.d1, value: d.decision1 },
                { config: round.d2, value: d.decision2 },
                { config: round.d3, value: d.decision3 }
            ];

            for (var i = 0; i < decisionSets.length; i++) {
                var dec = decisionSets[i];
                var opts = dec.config.options;
                for (var j = 0; j < opts.length; j++) {
                    if (opts[j].value === dec.value) {
                        learningGain += opts[j].learning;
                        safetyGain += opts[j].safety;
                        riskGain += opts[j].risk;
                        revenueGain += opts[j].revenue;
                        break;
                    }
                }
            }

            var learningDelta = learningGain * 3;
            var safetyDelta = safetyGain * 5;
            var riskDelta = riskGain * 5;

            state.domainState.learningScore = Math.max(0, Math.min(100, state.domainState.learningScore + learningDelta));
            state.domainState.safetyScore = Math.max(0, Math.min(100, state.domainState.safetyScore + safetyDelta));
            state.domainState.riskScore = Math.max(0, Math.min(100, state.domainState.riskScore + riskDelta));
            state.domainState.revenueProtected = Math.min(state.domainState.totalRevAtRisk, state.domainState.revenueProtected + revenueGain);

            var maxPossible = 0;
            var allDecs = [round.d1, round.d2, round.d3];
            for (var k = 0; k < allDecs.length; k++) {
                var bestTotal = 0;
                for (var m = 0; m < allDecs[k].options.length; m++) {
                    var optTotal = allDecs[k].options[m].learning + Math.max(0, allDecs[k].options[m].safety) + allDecs[k].options[m].risk;
                    if (optTotal > bestTotal) bestTotal = optTotal;
                }
                maxPossible += bestTotal;
            }
            var actualTotal = learningGain + Math.max(0, safetyGain) + riskGain;
            var roundScore = maxPossible > 0 ? Math.round((actualTotal / maxPossible) * 100) : 0;

            state.domainState.learningHistory.push(state.domainState.learningScore);
            state.domainState.safetyHistory.push(state.domainState.safetyScore);
            state.domainState.riskHistory.push(state.domainState.riskScore);
            state.domainState.revenueHistory.push(state.domainState.revenueProtected);
            state.domainState.roundScoreHistory.push(roundScore);

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackText) {
                feedbackPanel.style.display = 'block';
                var fbLevel = '_low';
                if (roundScore >= 80) fbLevel = '_high';
                else if (roundScore >= 50) fbLevel = '_mid';
                feedbackText.innerHTML = window.mySimulation.t(round.feedbackKey + fbLevel);
            }

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: state.currentPeriod,
                roundScore: roundScore,
                learningGain: learningDelta,
                safetyGain: safetyDelta,
                riskGain: riskDelta,
                revenueGain: revenueGain,
                learningScore: state.domainState.learningScore,
                safetyScore: state.domainState.safetyScore,
                riskScore: state.domainState.riskScore,
                revenueProtected: state.domainState.revenueProtected
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('learningDisplay', 'domainState.learningScore', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('safetyDisplay', 'domainState.safetyScore', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('riskDisplay', 'domainState.riskScore', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('revenueDisplay', 'domainState.revenueProtected', function(v) { return '\u20ac' + Math.round(v).toLocaleString(); });
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn) { undoBtn.addEventListener('click', function() { if (window.mySimulation && window.mySimulation.state) self._updateBriefing(window.mySimulation.state); }); }
        }

        getChartConfig() {
            return {
                metricsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Organizational Learning',
                                data: [],
                                borderColor: '#3182ce',
                                backgroundColor: 'rgba(49,130,206,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: 'Psychological Safety',
                                data: [],
                                borderColor: '#38a169',
                                backgroundColor: 'rgba(56,161,105,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            },
                            {
                                label: 'Risk Mitigation',
                                data: [],
                                borderColor: '#d69e2e',
                                backgroundColor: 'rgba(214,158,46,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Organizational Metrics Over Rounds' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.learningHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                metricsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.learningHistory },
                        { data: state.domainState.safetyHistory },
                        { data: state.domainState.riskHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = Math.round(totalScore / scores.length);
            var lastEntry = history[history.length - 1];
            var finalLearning = lastEntry.results ? lastEntry.results.learningScore || 0 : 0;
            var finalSafety = lastEntry.results ? lastEntry.results.safetyScore || 0 : 0;
            var finalRisk = lastEntry.results ? lastEntry.results.riskScore || 0 : 0;
            var finalRevenue = lastEntry.results ? lastEntry.results.revenueProtected || 0 : 0;

            var performance = 'Needs Improvement';
            if (avgScore >= 80 && finalLearning >= 70 && finalSafety >= 60) performance = 'Excellent';
            else if (avgScore >= 60 && finalLearning >= 50) performance = 'Good';
            else if (avgScore >= 40) performance = 'Fair';

            var insights = [];
            if (finalLearning >= 70) {
                insights.push('Strong systemic analysis — the organization can learn from failure effectively.');
            } else {
                insights.push('The analysis stayed too close to surface-level causes. Push deeper with the 5 Whys next time.');
            }
            if (finalSafety >= 60) {
                insights.push('High psychological safety — team members feel safe reporting problems early.');
            } else {
                insights.push('Low psychological safety may cause future problems to be hidden until they escalate.');
            }
            if (finalRevenue >= 700000) {
                insights.push('Significant revenue protected through proactive risk mitigation.');
            } else {
                insights.push('More revenue could have been protected with stronger preventive actions.');
            }

            return {
                avgScore: avgScore,
                finalLearning: finalLearning,
                finalSafety: finalSafety,
                finalRisk: finalRisk,
                revenueProtected: finalRevenue,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.roundScore < 40) return window.mySimulation.t('hint_low_score');
            if (results.safetyGain < 0) return window.mySimulation.t('hint_safety_drop');
            if (results.roundScore >= 80) return window.mySimulation.t('hint_great');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundScore', label: 'Round Score', i18nKey: 'col_score', formatter: function(v) { return v + '%'; } },
                { key: 'results.learningScore', label: 'Learning', i18nKey: 'col_learning' },
                { key: 'results.safetyScore', label: 'Safety', i18nKey: 'col_safety' },
                { key: 'results.riskScore', label: 'Risk Mitigation', i18nKey: 'col_risk' },
                { key: 'results.revenueProtected', label: 'Revenue Protected', i18nKey: 'col_revenue', formatter: function(v) { return '\u20ac' + Math.round(v).toLocaleString(); } }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:             `El Después`,
                    subtitle:          `After-Action Review, Pre-Mortem and Organizational Learning`,
                    round_label:       `Round`,
                    period_of:         `of`,
                    learning_label:    `Organizational Learning`,
                    safety_label:      `Psychological Safety`,
                    risk_label:        `Risk Mitigation`,
                    revenue_label:     `Revenue Protected`,
                    decisions_heading: `Your Decisions`,
                    submit_btn:        `Submit Round`,
                    undo_btn:          `Undo Last Round`,
                    feedback_heading:  `Round Feedback`,
                    select_warning:    `Please select an option for all three decisions`,

                    round1_title:      `Round 1 — Design the AAR Without a Witch Hunt`,
                    round1_briefing:   `Atrium Strategy Consulting just closed the Banco Castellano project: €480K in fees, but delivered 8 weeks late with a client NPS of 5/10. The scoring model was not calibrated for the client portfolio and the training was too theoretical for their analysts.<br><br>Engagement Manager Ignacio Llorente was fired 3 weeks ago. The dominant narrative is that it was his fault.<br><br>You must design the After-Action Review process. The goal: systemic learning — not validating the existing blame narrative. Three similar projects worth €1.1M total (Ibercaja €280K, Unicaja €390K, CaixaBank Risk €430K) are at risk of repeating the same failure pattern.`,

                    r1_d1_label:       `Who should facilitate the AAR?`,
                    r1_d1_opt1:        `Alvaro Herrera (Managing Partner) leads it internally`,
                    r1_d1_opt2:        `Bring in an external facilitator with no stake in the outcome`,
                    r1_d1_opt3:        `Carmen Vidal (responsible Partner) leads the review`,

                    r1_d2_label:       `How should the AAR begin?`,
                    r1_d2_opt1:        `Build a factual timeline of project events first — no judgments`,
                    r1_d2_opt2:        `Open discussion — let people share their perspectives freely`,
                    r1_d2_opt3:        `Start by identifying what went wrong and who was involved`,

                    r1_d3_label:       `How to include the perspective of Ignacio Llorente (fired EM)?`,
                    r1_d3_opt1:        `Conduct a separate private interview with Ignacio`,
                    r1_d3_opt2:        `Invite Ignacio to participate in the group AAR session`,
